"""Create a fresh profile and sign in to an existing X account."""

import json
import os
import re
from pathlib import Path

from account_input import parse_account
import setup_login as setup

values = context.inputs
last_stage = None


def stage(identifier):
    global last_stage
    if identifier != last_stage:
        context.stage(identifier)
        last_stage = identifier


def fail_preflight():
    context.fail("preflight_failed")


def optional_text(name):
    value = values.get(name)
    if value in (None, ""):
        return None
    if not isinstance(value, str):
        fail_preflight()
    return value


stage("validate")
try:
    account = parse_account(values.get("account_record"))
except (ValueError, TypeError):
    fail_preflight()

profile_id = optional_text("profile_id")
proxy_source = optional_text("proxy_library_id")
display_name = optional_text("name")
if profile_id is not None and not setup.PROFILE_ID.fullmatch(profile_id):
    fail_preflight()
if display_name is not None and (
    not 1 <= len(display_name) <= 255
    or any(ord(character) < 32 or ord(character) == 127 for character in display_name)
):
    fail_preflight()
if profile_id and display_name:
    fail_preflight()

manager_url = setup.profiles.validate_manager_url(context.manager_url)
receipt_path = Path(context.run_dir) / "setup-receipt.json"
original_request = setup.profiles.manager_request
original_update = setup.profiles.RunReceipt.update
original_prompt = setup.hidden_proxy
phase_stages = {
    "prepared": "prepare_profile",
    "profile_selected": "prepare_profile",
    "create_requested": "create_profile",
    "profile_created": "create_profile",
    "desktop_requested": "desktop",
    "desktop_selected": "desktop",
    "launch_requested": "launch_browser",
    "browser_running": "launch_browser",
    "login_requested": "login",
    "authenticated": "restore_recorder",
    "complete": "complete",
}


def manager_request(manager, path, payload=None, *, timeout=120):
    # The worker supplies this app's current authenticated connection privately.
    if setup.profiles.validate_manager_url(manager) != manager_url:
        fail_preflight()
    return context.manager_request(path, payload, timeout=timeout)


def receipt_update(receipt, phase, **fields):
    # Save recovery evidence before publishing only a fixed stage identifier.
    original_update(receipt, phase, **fields)
    if fields.get("recorderPauseRequested") is True:
        stage("pause_recorder")
    elif "recorderPriorState" in fields:
        stage("pause_recorder")
    elif phase in phase_stages:
        stage(phase_stages[phase])


def no_proxy_prompt():
    # An app worker must never wait for a hidden Terminal prompt.
    fail_preflight()


def library_proxy(source):
    stage("select_proxy")
    if source is None:
        context.fail("missing_proxy_source")
    if not setup.PROFILE_ID.fullmatch(source):
        context.fail("proxy_source_invalid")
    try:
        config = context.proxy_config(source)
        credential = setup.profiles.proxy_credential_from_profile({"proxy_config": config})
    except (RuntimeError, ValueError, KeyError, TypeError):
        context.fail("proxy_source_invalid")
    return {"proxy_credential": credential, "proxy_library_id": source}


setup.profiles.manager_request = manager_request
setup.profiles.RunReceipt.update = receipt_update
setup.hidden_proxy = no_proxy_prompt
try:
    proxy_options = {}
    arguments = [
        "--manager-url", manager_url,
        "--no-start-manager",
        "--no-controls",
    ]
    if context.resume_dir is not None:
        if profile_id or display_name:
            fail_preflight()
        stage("prepare_profile")
        prior_path = Path(context.resume_dir) / "setup-receipt.json"
        if not prior_path.is_file() or prior_path.stat().st_size > 1024 * 1024:
            fail_preflight()
        try:
            prior = setup.resume_receipt(prior_path, lab=False)
        except (RuntimeError, ValueError, OSError, KeyError, TypeError):
            fail_preflight()
        if prior.data.get("profileId") is None:
            source = prior.data.get("proxySourceLibrary")
            if not isinstance(source, str) or not setup.PROFILE_ID.fullmatch(source):
                context.fail("proxy_source_invalid")
            if proxy_source is None:
                context.fail("missing_proxy_source")
            if source != proxy_source:
                context.fail("proxy_source_invalid")
            proxy_options = library_proxy(source)
        # Keep each attempt's own receipt so repeated Resume operations work.
        # Only safe setup metadata is copied; the prior attempt stays unchanged.
        copied = dict(prior.data)
        copied["manager"] = manager_url
        descriptor = os.open(receipt_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(descriptor, "w", encoding="utf-8") as output:
            json.dump(copied, output)
            output.write("\n")
            output.flush()
            os.fsync(output.fileno())
        arguments.extend(["--resume", str(receipt_path)])
    elif profile_id:
        arguments.extend(["--profile-id", profile_id, "--receipt", str(receipt_path)])
    else:
        # Resolve only the selected library capability; credentials stay in memory.
        proxy_options = library_proxy(proxy_source)
        arguments.extend([
            "--minutes", str(values.get("minutes", "120")),
            "--receipt", str(receipt_path),
        ])
        if display_name:
            arguments.extend(["--name", display_name])
    seed = values.get("seed")
    if seed is not None and seed != "":
        if type(seed) is not int:
            fail_preflight()
        arguments.extend(["--seed", str(seed)])
    if values.get("current_desktop") is True:
        arguments.append("--current-desktop")
    try:
        options = setup.parser().parse_args(arguments)
    except SystemExit:
        fail_preflight()
    result = setup.execute(account, options, **proxy_options)
    identifier = result.get("profileId")
    if (
        not isinstance(identifier, str)
        or not setup.PROFILE_ID.fullmatch(identifier)
        or result.get("authenticated") is not True
    ):
        context.fail("script_error")
    summary = {
        "profile_id": identifier,
        "authenticated": True,
        "totp_used": result.get("totpUsed") is True,
        "recorder_restored": result.get("recorderRestored") is True,
    }
    city = result.get("city")
    if city is not None:
        if not isinstance(city, str) or not re.fullmatch(r"[A-Za-z0-9_-]{1,100}", city):
            context.fail("script_error")
        summary["city"] = city
    context.set_result(summary)
    stage("complete")
finally:
    setup.profiles.manager_request = original_request
    setup.profiles.RunReceipt.update = original_update
    setup.hidden_proxy = original_prompt
